-- Generated by inferlo db migrate. Review before applying with: inferlo db migrate --apply

CREATE TABLE IF NOT EXISTS "users" (
  "id" uuid PRIMARY KEY,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "email" text NOT NULL,
  "name" varchar(80) NOT NULL,
  "role" text DEFAULT 'member' NOT NULL CHECK ("role" IN ('member', 'admin'))
);

CREATE UNIQUE INDEX IF NOT EXISTS "users_email_key" ON "users" ("email");

CREATE TABLE IF NOT EXISTS "api_keys" (
  "id" uuid PRIMARY KEY,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
  "hash" varchar(64) NOT NULL,
  "label" varchar(80) DEFAULT 'default' NOT NULL
);

CREATE INDEX IF NOT EXISTS "api_keys_user_id_idx" ON "api_keys" ("user_id");

CREATE UNIQUE INDEX IF NOT EXISTS "api_keys_hash_key" ON "api_keys" ("hash");

CREATE TABLE IF NOT EXISTS "notes" (
  "id" uuid PRIMARY KEY,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "title" varchar(200) NOT NULL,
  "body" text DEFAULT '' NOT NULL,
  "color" varchar(20),
  "owner_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
  "pinned" boolean DEFAULT false NOT NULL
);

CREATE INDEX IF NOT EXISTS "notes_color_idx" ON "notes" ("color");

CREATE INDEX IF NOT EXISTS "notes_owner_id_idx" ON "notes" ("owner_id");
